{
  "name": "端口读出组件",
  "name_en": "Port Reader Helper",
  "manufacturer": "",
  "description": "一个非物理的软件组件，用于在实验流程中从通用通信端口读取数据、缓存读数，并以普通读出或 NumPy 数组形式提供结果。",
  "description_en": "A non-physical software component for reading data from a generic communication port in laboratory workflows, buffering readouts, and providing results as standard readouts or NumPy arrays.",
  "actions": [
    {
      "action_name": "auto-clear_array",
      "description": "清空缓存数据数组。",
      "description_en": "Clear the buffered data array."
    },
    {
      "action_name": "auto-thread_foo",
      "description": "执行组件的线程例程。",
      "description_en": "Run the component's thread routine."
    },
    {
      "action_name": "auto-takeReadout",
      "description": "获取一次端口读出。",
      "description_en": "Take a readout from the port."
    },
    {
      "action_name": "auto-takeNpArray",
      "description": "以 NumPy 数组形式获取数据。",
      "description_en": "Get the data as a NumPy array."
    },
    {
      "action_name": "auto-close_PortReader",
      "description": "关闭端口读出组件。",
      "description_en": "Close the port reader component."
    }
  ],
  "tag_hints": [
    "port I/O",
    "data acquisition helper",
    "readout buffering",
    "NumPy array export",
    "threaded polling",
    "generic lab software"
  ]
}

